"use client";

import * as React from "react";
import { motion, useMotionValue, useSpring, useReducedMotion } from "motion/react";
import styles from "../styles/magnetic-button.module.css";

/** Native button attributes whose names collide with Motion's animation and gesture handlers. */
type MotionConflictingKeys = "onAnimationStart" | "onDrag" | "onDragStart" | "onDragEnd";

export interface MagneticButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, MotionConflictingKeys> {
  /** Button label */
  label?: string;
  /** Attraction strength multiplier */
  strength?: number;
  /** Return spring stiffness */
  stiffness?: number;
  /** Return spring damping */
  damping?: number;
  /** Hover scale multiplier */
  hoverScale?: number;
  /** Visual variant */
  variant?: "solid" | "outline" | "ghost";
}

export function MagneticButton({
  children,
  label = "Explore 24 Components",
  strength = 0.36,
  stiffness = 230,
  damping = 18,
  hoverScale = 1.04,
  variant = "solid",
  className = "",
  ...rest
}: MagneticButtonProps) {
  const ref = React.useRef<HTMLButtonElement>(null);
  const prefersReducedMotion = useReducedMotion();

  const rawX = useMotionValue(0);
  const rawY = useMotionValue(0);
  const x = useSpring(rawX, { stiffness, damping, mass: 0.4 });
  const y = useSpring(rawY, { stiffness, damping, mass: 0.4 });

  const handlePointerMove = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (prefersReducedMotion || e.pointerType === "touch" || !ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    const dx = (e.clientX - (rect.left + rect.width / 2)) * strength;
    const dy = (e.clientY - (rect.top + rect.height / 2)) * strength;
    rawX.set(dx);
    rawY.set(dy);
  };

  const handlePointerLeave = () => {
    rawX.set(0);
    rawY.set(0);
  };

  return (
    <motion.button
      ref={ref}
      type="button"
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      whileHover={prefersReducedMotion ? undefined : { scale: hoverScale }}
      whileTap={prefersReducedMotion ? undefined : { scale: 0.97 }}
      style={{
        x: prefersReducedMotion ? 0 : x,
        y: prefersReducedMotion ? 0 : y,
      }}
      className={`${styles.button} ${styles[variant]} ${className}`.trim()}
      {...rest}
    >
      <span className={styles.label}>{children ?? label}</span>
    </motion.button>
  );
}

.button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.7rem 1.35rem;
  border-radius: 0.625rem;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  user-select: none;
  will-change: transform;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease;
}

.button:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

.solid {
  background-color: var(--mf-fg, #f4f4f6);
  color: var(--mf-bg, #09090b);
  border: 1px solid var(--mf-fg, #f4f4f6);
}

.solid:hover {
  background-color: #ffffff;
}

.outline {
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  border: 1px solid var(--mf-border, #2e2e38);
}

.outline:hover {
  border-color: var(--mf-border-strong, #52525b);
}

.ghost {
  background-color: transparent;
  color: var(--mf-fg, #d4d4d8);
  border: 1px solid transparent;
}

.ghost:hover {
  background-color: rgba(39, 39, 42, 0.5);
}

.label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  .button {
    transform: none !important;
  }
}

