"use client";

import * as React from "react";
import { motion, useMotionValue, useSpring } from "motion/react";

export function MagneticButtonTailwind({ label = "Explore 24 Components" }) {
  const x = useSpring(useMotionValue(0), { stiffness: 230, damping: 18 });
  const y = useSpring(useMotionValue(0), { stiffness: 230, damping: 18 });
  return (
    <motion.button
      type="button"
      style={{ x, y }}
      onPointerMove={(e) => {
        if (e.pointerType === "touch") return;
        const r = e.currentTarget.getBoundingClientRect();
        x.set((e.clientX - (r.left + r.width / 2)) * 0.36);
        y.set((e.clientY - (r.top + r.height / 2)) * 0.36);
      }}
      onPointerLeave={() => { x.set(0); y.set(0); }}
      className="rounded-lg bg-zinc-100 px-5 py-2.5 text-sm font-medium text-zinc-950"
    >
      {label}
    </motion.button>
  );
}
